import { useState, useEffect } from "react"

function BooksFromTheServer() {
  const [books, setBooks] = useState([])
    useEffect(() => {

        fetch("/api/to-read")
          .then(resp => resp.json())
          .then(data => setBooks(data)) 
  }, []) 


  function handleOpinionClick(evt) {
    evt.target.innerHTML += `<br> ${parseInt(evt.target.id)}` 
  }  
  return (
    <>
    {
        books.map((book, index) => (
          <li key={index} id={index} onClick={handleOpinionClick}><i>{book.title} - {book.author}</i></li>
        ))

    }
    </>
  )
}

export default function ToRead(){

  return (
    <>
      <h2>Books To read</h2>
      <div className="list-container">
        <div className="book-list">
          <ul>
            <BooksFromTheServer/> 
          </ul>
        </div>
      </div>
    </>
  )  
}
